mapper.select:
select coalesce(avg(abs(deviation_rate)), 0)
from finance_cashflow_forecast_snapshot
where forecast_date >= date_sub(curdate(), interval 30 day)
and dept_id = #{params.deptId}

    and dept_id in

        #{deptId}

select coalesce(( select sum(p.payment_amount) from fin_sale_payment p join fin_sale_record r on p.sale_id = r.sale_id where p.del_flag = '0' and p.payment_date >= date_sub(curdate(), interval 7 day) and r.dept_id = #{params.deptId}
and r.dept_id in
#{deptId}
), 0) - coalesce(( select sum(e.expense_amount) from fin_expense e where e.del_flag = '0' and e.verify_status = 'VERIFIED' and e.expense_date >= date_sub(curdate(), interval 7 day)
), 0)
